'use strict';
// On-device development audit. Uses real campaign updates without drawing each tick.
// It measures objective/bot behavior, NOT FPS, human difficulty, or engagement.
const Audit=(()=>{
let active=false,rows=[],w=0,l=1,ticks=0,seed=1,backup=null,random=null,frameId=null,mission=null,priorWorld=0,priorLevel=1;
function begin(){if(active||typeof V!=='undefined'&&V.active)return;Debug.cancel();C.open('home');priorWorld=C.world;priorLevel=C.level;backup=JSON.parse(JSON.stringify(C.data));random=Math.random;active=true;rows=[];w=0;l=1;const box=document.createElement('dialog');box.id='auditDialog';box.innerHTML='<h3>500-LEVEL ON-DEVICE SIMULATION</h3><p>Real physics and AI with scripted steering. No rendering benchmark or human playtest. Rewards disabled; campaign save is preserved.</p><pre id="auditProgress"></pre><button id="auditCancel">CANCEL</button><textarea id="auditResult" readonly aria-label="Campaign audit JSON"></textarea>';document.body.append(box);box.showModal();box.querySelector('button').onclick=()=>{if(active)finish('Cancelled');else{box.close();box.remove()}};box.addEventListener('cancel',e=>{e.preventDefault();if(active)finish('Cancelled');else{box.close();box.remove()}});next();frameId=requestAnimationFrame(batch)}
function next(){seed=10000+w*100+l;Math.random=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);C.auditSelect(w,l);C.data.selected=0;C.data.upgrades={};start();ticks=0;mission=C.mission()}
function steer(){let goal;const layout=C.auditLayout();if(mission.type==='route')goal=layout.points[layout.checkpoint];else if(mission.type==='salvage')goal=layout.points.filter(p=>!p.taken).sort((a,b)=>Math.hypot(player.x-a.x,player.y-a.y)-Math.hypot(player.x-b.x,player.y-b.y))[0];else{const a=elapsed*.36;goal={x:Math.cos(a)*370,y:Math.sin(a)*370}}if(typeof Rescue!=='undefined'&&Rescue.active&&Rescue.phase!=='objective')goal=Rescue.phase==='return'?Rescue.home:Rescue.targets.find(p=>!p.taken);if(!goal)return;let dx=goal.x-player.x,dy=goal.y-player.y,len=Math.hypot(dx,dy)||1;dx/=len;dy/=len;for(const o of obstacles){const ox=player.x-o.x,oy=player.y-o.y,d=Math.hypot(ox,oy);if(d<o.r+110&&(-ox*dx-oy*dy)>-o.r){const force=(o.r+110-d)/65;dx+=ox/(d||1)*force*2;dy+=oy/(d||1)*force*2}}pointer={id:-1};stick={x:dx*35,y:dy*35};if(S.charge>=85&&len>180)S.boost()}
function batch(){if(!active)return;try{const endTime=performance.now()+8;do{steer();update(1/60);ticks++;if(!Number.isFinite(player.x)||!Number.isFinite(player.hp))throw Error('Invalid physics state');if(state!=='playing'||ticks>=9000){rows.push({world:w,level:l,type:mission.type,outcome:state==='over'?(player.hp>0?'won':'busted'):'timeout',seconds:+elapsed.toFixed(2),hull:+player.hp.toFixed(1),wrecks:kills});if(++l>100){l=1;w++}if(w>=5){finish('Completed');return}next()}}while(performance.now()<endTime);document.getElementById('auditProgress').textContent=`${rows.length}/500 complete · world ${w+1} level ${l}\nScripted starter car · no upgrades`;frameId=requestAnimationFrame(batch)}catch(e){finish('Stopped: '+e.message)}}
function finish(status){if(!active)return;C.auditSelect(priorWorld,priorLevel);active=false;cancelAnimationFrame(frameId);Math.random=random;Object.keys(C.data).forEach(k=>delete C.data[k]);Object.assign(C.data,backup);pointer=null;stick={x:0,y:0};Object.keys(keys).forEach(k=>keys[k]=false);state='hub';C.open('home');const counts=Array.from({length:5},(_,world)=>{const r=rows.filter(v=>v.world===world);return{world:world+1,runs:r.length,won:r.filter(v=>v.outcome==='won').length,busted:r.filter(v=>v.outcome==='busted').length,timeout:r.filter(v=>v.outcome==='timeout').length}});document.getElementById('auditProgress').textContent=`${status}: ${rows.length}/500\n`+counts.map(r=>`World ${r.world}: ${r.won} wins / ${r.runs} attempts`).join('\n');document.getElementById('auditResult').value=JSON.stringify({method:'On-device real-engine scripted simulation; not a rendering or human playtest',status,counts,rows},null,2);document.getElementById('auditCancel').textContent='CLOSE'}
return{begin,get active(){return active}};
})();
